const fs = require('fs');
const path = require('path');
const vmm = require('vm');
const SRC = JSON.parse(fs.readFileSync(path.join(__dirname, 'src_g4_social_u1.json'), 'utf8'));
const OUT = path.join(__dirname, '..', 'data', 'g4_social_u1.js');
const DIR = '1단원_지도로만나는우리지역';
const LIVE = '../../grade4/semester1/social/' + DIR + '/';
const UNIT = 1, UT = '지도로 만나는 우리 지역', PREV_KEY = 'g3s2_social:u2_l08';

const TN = (a1, a2, watch, min) => ({ ask: [a1, a2], watch, min });
const nm = (s) => String(s || '').replace(/\*\*/g, '');
const EMO = /[\u{1F000}-\u{1FFFF}\u2600-\u27BF\u2B00-\u2BFF\uFE0F\u200D\u20E3]/gu;
const plain = (s) => nm(s).replace(EMO, '').replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
const SL = (k, i) => SRC[k].slides.find(x => x.i === i);
const BD = (k) => SRC[k].board_data;
/* 판 아닌 개념 장 카드: rows [[그림, 이름, 아래 줄]] — 이름·아래 줄은 원문 장 글 토막 */
const cards = (rows, chain) => ({ k: chain ? 'chain' : 'tools', items: rows.map(r => ({ emoji: r[0], name: r[1], kind: r[2] || undefined })) });

/* 앞 단원(3-2 사회 2단원) 마지막 키 u2_l08 출구 — 생성된 2세대 데이터에서 그대로 읽는다 */
const PREV_EXIT = (() => { const L = {}; const c = { window: { LESSONS: L }, LESSONS: L }; c.window.window = c.window; vmm.createContext(c); vmm.runInContext(fs.readFileSync(path.join(__dirname, '..', 'data', 'g3s2_social_u2.js'), 'utf8'), c); return L.u2_l08.slides.find(s => s.block === 'exit_ticket').data.items; })();

/* ── 판 그림(원문 판의 표 그대로) ── */
const PL_EMO = { school: '🏫', apt: '🏢', market: '🧺', hospital: '🏥', mountain: '⛰️', river: '🏞️', post: '📮', fire: '🚒', police: '👮' };
const SYM1 = { school: '깃발 기호', apt: '검은 네모 기호', market: '약속된 기호와 색', hospital: '십자(＋) 기호', mountain: '초록 세모 · 높이 숫자', river: '파란 선' }; // l01 — 원문 desc 의 토막(게이트 M)
const SYM3 = { school: ['🚩', '깃발'], post: ['🕊️', '제비'], hospital: ['➕', '십자(＋)'], fire: ['🔥', '불꽃'], police: ['🛡️', '방패와 별'], mountain: ['🔺', '세모(▲)'] }; // l03 — 원문 기호 그림(sym)의 모양 이름
const DIR8 = ['n', 'e', 's', 'w', 'ne', 'se', 'sw', 'nw'];
const BAND_EMO = ['🟩', '🟨', '🟧', '🟫', '⛰️'];
const PX_ROWS = (b) => Math.max.apply(null, b.PIXELS.reduce((a, p) => a.concat(p.cells.map(c => c[1])), [])) + 1;
const BOARD = {
  u1_l01: () => { const P = BD('u1_l01').PLACES; return { k: 'link', ha: '하늘 사진 속 장소', hb: '지도에서는', rows: Object.keys(P).map(k => [{ emoji: PL_EMO[k], name: P[k].name }, { name: SYM1[k] }]), note: '장소 ' + Object.keys(P).length + '곳이 모두 **약속된 기호**로 바뀌면 사진이 **지도**가 돼요' }; },
  u1_l02: () => { const P = BD('u1_l02').PLACES; const chip = (d) => ({ emoji: P[d].emoji, name: P[d].ko + '쪽 · ' + P[d].name }); return { k: 'groups', bins: [{ name: '4방위 (동·서·남·북)', emoji: '🧭', tone: 't0', items: DIR8.slice(0, 4).map(chip) }, { name: '그 사이 방위 (8방위)', emoji: '✳️', tone: 't1', items: DIR8.slice(4).map(chip) }] }; },
  u1_l03: () => { const P = BD('u1_l03').PLACES; return { k: 'link', ha: '범례 — 기호', hb: '뜻', rows: Object.keys(P).map(k => [{ emoji: SYM3[k][0], name: SYM3[k][1] }, { emoji: PL_EMO[k], name: P[k].name }]), note: '기호 ' + Object.keys(P).length + '개와 뜻을 한곳에 모으면 **범례**가 돼요' }; },
  u1_l04: () => { const B = BD('u1_l04').BANDS; return { k: 'chain', items: B.map((b, i) => ({ emoji: BAND_EMO[i], name: b.label, kind: i ? '한 칸 안쪽 · 더 높아요' : '가장 바깥 · 낮은 땅' })) }; },
  u1_l05: () => { const b = BD('u1_l05'), L0 = b.LOC; const pair = (i, j) => { const cm = L0[j].gx - L0[i].gx; return [{ emoji: '📍', name: L0[i].name + ' → ' + L0[j].name }, { name: '지도상 ' + cm + ' cm = 실제 ' + cm + ' km' }]; }; return { k: 'link', ha: '두 곳(축척 1 cm = 1 km)', hb: '축척 막대자로 재면', rows: [pair(0, 1), pair(1, 2), pair(2, 3), pair(0, 3)], same: true }; },
  u1_l06: () => { const S = BD('u1_l06').STATIONS; const st = (k) => S.find(x => x.k === k); const a = st('stadium'), t = st('suyeong'), z = st('haeundae'); return { k: 'chain', items: [{ emoji: '🟠', name: a.name + '역', kind: a.lines[0] + '호선에서 출발' }, { emoji: '🔁', name: t.name + '역', kind: '갈아타요 · ' + a.lines[0] + '호선 → ' + z.lines[0] + '호선' }, { emoji: '🔵', name: z.name + '역', kind: z.lines[0] + '호선으로 도착' }] }; },
  u1_l07: () => { const E = BD('u1_l07').ELEMENTS; const EM = { compass: '🧭', symbol: '➕', contour: '〰️', scale: '📏' }; return { k: 'tools', items: E.map(e => ({ emoji: EM[e.k], name: e.name, kind: plain(e.desc) })) }; },
  u1_l08: () => { const F = BD('u1_l08').LANDFORMS; return { k: 'tools', items: F.map(f => ({ emoji: f.emoji, name: f.name, kind: plain(f.desc) })) }; },
  u1_l09: () => { const Y = BD('u1_l09').YEARS; return { k: 'sbars', title: '우리 지역 인구 (예시 자료)', x: Y.map(y => y.year), v: Y.map(y => y.pop), unit: '만 명', yl: '만 명', hi: [0, Y.length - 1], cmp: true }; },
  u1_l10: () => { const S = BD('u1_l10').SEASONS; return { k: 'sbars', title: '계절별 강수량 (예시 자료 · 막대)', x: S.map(s => s.name), v: S.map(s => s.precip), unit: 'mm', yl: 'mm', hi: [1, 3], caption: '기온(꺾은선): ' + S.map(s => s.name + ' ' + s.temp + '°C').join(' · ') }; },
  u1_l11: () => { const G = BD('u1_l11').GEOINFO; return { k: 'tools', items: G.map(g => ({ emoji: g.icon, name: g.name, kind: '우리 지역 ' + g.ours + ' ↔ 다른 지역 ' + g.other, keep: true })) }; },
  u1_l12: () => { const b = BD('u1_l12'), W = b.GRID_COLS, H = PX_ROWS(b); const cells = []; for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) { const k = b.PIXELS.findIndex(p => p.cells.some(c => c[0] === x && c[1] === y)); cells.push({ name: k >= 0 ? String(k + 1) : '', k: k >= 0 ? k : -1 }); } return { k: 'led', cols: W, kinds: b.PIXELS.map(p => p.name), colors: b.PIXELS.map(p => p.color), cells, offName: '빈 칸', caption: '칸 수: ' + b.PIXELS.map(p => p.name + ' ' + p.cells.length + '칸').join(' · ') + ' → 칸이 많을수록 **면적이 넓어요**' }; },
  u1_l13: () => { const T0 = BD('u1_l13').TERMS; const EM = { compass: '🧭', legend: '📋', contour: '〰️', land: '⛰️', pop: '👥', climate: '🌡️' }; const bin = (tp, name, tone) => ({ name, emoji: tp === '①' ? '🗺️' : '📍', tone, items: T0.filter(t => t.topic === tp).map(t => ({ emoji: EM[t.k], name: t.name })) }); return { k: 'groups', bins: [bin('①', '① 지도의 요소', 't0'), bin('②', '② 우리 지역의 지리 정보', 't1')] }; }
};

